using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class ActorInspectorOperations
{
    private static void Hint(Control owner,Control input,string text){var hints=owner.Get("hints").AsGodotObject();if(hints!=null){if(text.Length>0)hints.Call("begin",input,text);else hints.Call("end",input);}}
    public SpinBox number(Control owner,double value,double step){var input=new DragNumber();input.AllowGreater=true;input.AllowLesser=true;input.Step=step;input.Value=value;input.UpdateOnTextChanged=false;input.SizeFlagsHorizontal=Control.SizeFlags.ExpandFill;input.Connect("interaction_started",Callable.From(()=>Hint(owner,input,"Esc cancels drag")));input.Connect("interaction_ended",Callable.From(()=>Hint(owner,input,"")));return input;}
    public SpinBox number_editor(Control owner,Control parent,double value,Resource property)
    {
        var options=property.Get("options").AsGodotDictionary();var row=new HBoxContainer();row.AddThemeConstantOverride("separation",8);parent.AddChild(row);var input=number(owner,value,options.GetValueOrDefault("step",property.Get("value_type").AsInt32()==(int)Variant.Type.Int?1.0:.01).AsDouble());input.Name=property.Get("id").AsString()+"_value";if(options.ContainsKey("min")&&options.ContainsKey("max")){var slider=new HSlider{Name=property.Get("id").AsString()+"_slider",MinValue=options["min"].AsDouble(),MaxValue=options["max"].AsDouble(),Step=input.Step,Value=value,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};slider.TooltipText=$"{slider.MinValue} to {slider.MaxValue}";row.AddChild(slider);input.CustomMinimumSize=new Vector2(82,0);input.SizeFlagsHorizontal=Control.SizeFlags.ShrinkEnd;input.TooltipText=$"Slider: {slider.MinValue} to {slider.MaxValue}. Drag or type to go outside that range.";input.SetMeta("range_slider",slider);bool dragging=false;slider.DragStarted+=()=>{dragging=true;input.EmitSignal("interaction_started");};slider.ValueChanged+=updated=>{input.SetValueNoSignal(updated);input.EmitSignal(dragging?"preview_changed":"value_changed",updated);};slider.DragEnded+=changed=>{dragging=false;input.EmitSignal("interaction_ended");if(changed)input.EmitSignal("drag_committed",input.Value);};input.Connect("preview_changed",Callable.From<double>(slider.SetValueNoSignal));input.ValueChanged+=slider.SetValueNoSignal;}row.AddChild(input);return input;
    }
    public void set_number_silent(SpinBox input,double value){input.SetValueNoSignal(value);if(input.HasMeta("range_slider")){var slider=input.GetMeta("range_slider").As<HSlider>();if(GodotObject.IsInstanceValid(slider))slider.SetValueNoSignal(value);}}
    public OptionButton choice_editor(Control parent,Resource property,int selected){var choice=new OptionButton{Name=property.Get("id").AsString()+"_choice",SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};foreach(var label in property.Get("options").AsGodotDictionary().GetValueOrDefault("choices",new Godot.Collections.Array()).AsGodotArray())choice.AddItem(label.ToString());choice.Select(Math.Clamp(selected,0,Math.Max(0,choice.ItemCount-1)));parent.AddChild(choice);return choice;}
    public void add_label(Control parent,string text)=>parent.AddChild(new Label{Text=text,AutowrapMode=TextServer.AutowrapMode.WordSmart});
    public VBoxContainer stateful_category(Control owner,string text,string id,VBoxContainer parent,string key)
    {
        var section=new VBoxContainer();section.AddThemeConstantOverride("separation",4);parent.AddChild(section);string category=key.Length==0?text:key+":"+text;var state=Ui<Resource>(owner,"ui_state");var header=new Button{Name=("Category_"+category).Replace(":","_").Replace("/","_"),Flat=true,ToggleMode=true,ButtonPressed=_state.category_expanded(state,id,category),Alignment=HorizontalAlignment.Left,Modulate=new Color("80dbc4")};section.AddChild(header);var content=new VBoxContainer{Name="Content",Visible=header.ButtonPressed};content.AddThemeConstantOverride("separation",4);section.AddChild(content);void Update(bool expanded)=>header.Text=(expanded?"▾  ":"▸  ")+text.ToUpperInvariant();Update(header.ButtonPressed);header.Toggled+=expanded=>{content.Visible=expanded;Update(expanded);_state.set_category_expanded(state,id,category,expanded);};return content;
    }
    public void scroll_changed(Control owner,double value){var actor=owner.Get("_actor").As<Resource>();if(!owner.Get("_restoring_scroll").AsBool()&&actor!=null&&!owner.Get("_inspecting_file").AsBool())_state.set_page_scroll(Ui<Resource>(owner,"ui_state"),actor.Get("id").AsString(),owner.Get("_main_tab").AsString(),owner.Get("_section").AsString(),value);}
    public void restore_scroll(Control owner,string id,int revision){var actor=owner.Get("_actor").As<Resource>();if(actor==null||actor.Get("id").AsString()!=id||(revision>=0&&revision!=owner.Get("_navigation_revision").AsInt32()))return;owner.Set("_restoring_scroll",true);string main=owner.Get("_main_tab").AsString(),section=owner.Get("_section").AsString();Ui<ScrollContainer>(owner,"content_scroll").ScrollVertical=(int)_state.page_scroll_for(Ui<Resource>(owner,"ui_state"),id,main,section);var pages=owner.Get("_sections").AsGodotDictionary();if(pages.TryGetValue(main+"/"+section,out var page))Ui<ScrollContainer>(owner,"section_scroll").EnsureControlVisible(page.AsGodotDictionary()["button"].As<Control>());owner.Set("_restoring_scroll",false);}
    public void prepare_buttons(Control owner){foreach(var node in Ui<Control>(owner,"fields").FindChildren("*","Button",true,false)){if(node is not Button button)continue;button.ActionMode=BaseButton.ActionModeEnum.Press;button.MouseFilter=Control.MouseFilterEnum.Stop;button.CustomMinimumSize=new Vector2(button.CustomMinimumSize.X,Math.Max(button.CustomMinimumSize.Y,24));int length=System.Linq.Enumerable.Count(button.Text.EnumerateRunes());button.ClipText=length>4;button.TextOverrunBehavior=button.ClipText?TextServer.OverrunBehavior.TrimEllipsis:TextServer.OverrunBehavior.NoTrimming;if(length<=3){button.AddThemeFontSizeOverride("font_size",12);button.CustomMinimumSize=new Vector2(Math.Max(button.CustomMinimumSize.X,24),button.CustomMinimumSize.Y);foreach(string variant in new[]{"normal","hover","pressed","hover_pressed","disabled"}){var style=(StyleBox)button.GetThemeStylebox(variant).Duplicate();style.ContentMarginLeft=4;style.ContentMarginRight=4;button.AddThemeStyleboxOverride(variant,style);}}if(button is OptionButton option)option.FitToLongestItem=false;}}
}
